import "./team-grid.css";

export interface TeamMember {
  name: string;
  role: string;
  avatar: string;
  bio: string;
}
export interface TeamGridProps {
  eyebrow: string;
  heading: string;
  columns: "2" | "3" | "4";
  shape: "circle" | "rounded";
  tone: "white" | "light";
  members: TeamMember[];
}

export function TeamGridRender({ eyebrow, heading, columns, shape, tone, members }: TeamGridProps) {
  return (
    <div className="p1-team-grid p1-block" data-tone={tone} data-cols={columns}>
      <div className="p1-team-grid__inner">
        <div className="p1-team-grid__header">
          {eyebrow && <p className="p1-team-grid__eyebrow">{eyebrow}</p>}
          {heading && <h2 className="p1-team-grid__heading">{heading}</h2>}
        </div>
        <div className="p1-team-grid__grid">
          {(members || []).map((m, i) => (
            <div key={i} className="p1-team-grid__member">
              <div className="p1-team-grid__avatar" data-shape={shape}>
                {m.avatar && <img src={m.avatar} alt={m.name} className="p1-team-grid__avatar-img" />}
              </div>
              <div className="p1-team-grid__name">{m.name}</div>
              <div className="p1-team-grid__role">{m.role}</div>
              {m.bio && <p className="p1-team-grid__bio">{m.bio}</p>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { TeamGridRender, type TeamGridProps, type TeamMember } from "./team-grid";
export type { TeamGridProps, TeamMember };

export const TeamGridBlock: ComponentConfig<TeamGridProps> = {
  fields: {
    eyebrow: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the heading. 2–4 words. E.g. The team." },
    },
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading. 4–8 words." },
    },
    columns: {
      type: "select" as const,
      options: [
        { label: "2", value: "2" },
        { label: "3", value: "3" },
        { label: "4", value: "4" },
      ],
    },
    shape: {
      type: "radio" as const,
      options: [
        { label: "Circle", value: "circle" },
        { label: "Rounded", value: "rounded" },
      ],
    },
    tone: {
      type: "radio" as const,
      options: [
        { label: "White", value: "white" },
        { label: "Light", value: "light" },
      ],
    },
    members: {
      type: "array" as const,
      arrayFields: {
        name: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Team member's full name." },
        },
        role: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Job title. E.g. Head of Operations." },
        },
        avatar: {
          type: "text" as const,
          ai: { exclude: true },
        },
        bio: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "1–2 sentence bio. Optional — leave blank to omit." },
        },
      },
      defaultItemProps: { name: "Team member", role: "Role", avatar: "", bio: "" },
      getItemSummary: (item: TeamMember) => item.name || "Member",
    },
  },
  defaultProps: {
    eyebrow: "The team",
    heading: "People behind the platform.",
    columns: "3",
    shape: "circle",
    tone: "white",
    members: [
      { name: "Jordan Ellis", role: "Head of Operations", avatar: wireframe(300, 300), bio: "" },
      { name: "Sam Rivera", role: "Principal Engineer", avatar: wireframe(300, 300), bio: "" },
      { name: "Priya Nair", role: "Design Lead", avatar: wireframe(300, 300), bio: "" },
    ],
  },
  render: TeamGridRender,
};

export const meta = defineMeta({
  title: 'Team Grid',
  description: 'Grid of team member cards with avatar, name, role, and bio in circle or rounded photo shape; use for About/Team pages.',
  categories: ["trust"],
  published: true,
});

.p1-team-grid[data-tone="light"] { background-color: var(--p1-surface-subtle); }

.p1-team-grid__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
}

.p1-team-grid__header {
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}
.p1-team-grid__eyebrow {
  color: var(--p1-accent);
  font-size: var(--p1-text-xl);
  font-style: italic;
  margin-block-end: var(--p1-space-sm);
}
.p1-team-grid__heading {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-team-grid__heading { font-size: var(--p1-text-3xl); }
}

.p1-team-grid__grid {
  display: grid;
  gap: var(--p1-space-lg);
  grid-template-columns: 1fr;
}
@media (width >= 40rem) {
  .p1-team-grid__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (width >= 64rem) {
  .p1-team-grid[data-cols="3"] .p1-team-grid__grid { grid-template-columns: repeat(3, 1fr); }
  .p1-team-grid[data-cols="4"] .p1-team-grid__grid { grid-template-columns: repeat(4, 1fr); }
}

.p1-team-grid__member {
  align-items: center;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  text-align: center;
}

.p1-team-grid__avatar {
  background-color: color-mix(in oklch, var(--p1-surface-inverse) 15%, transparent);
  block-size: 8rem;
  inline-size: 8rem;
  margin-block-end: var(--p1-space-sm);
  overflow: hidden;
}
.p1-team-grid__avatar[data-shape="circle"] { border-radius: var(--p1-radius-pill); }
.p1-team-grid__avatar[data-shape="rounded"] { border-radius: var(--p1-radius-card); }
.p1-team-grid__avatar-img { block-size: 100%; inline-size: 100%; object-fit: cover; }

.p1-team-grid__name {
  color: var(--p1-fg-default);
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
}
.p1-team-grid__role {
  color: var(--p1-accent);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-medium);
}
.p1-team-grid__bio {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  line-height: var(--p1-leading-normal);
  margin-block-start: var(--p1-space-sm);
  max-inline-size: 16rem;
}

